export var QUESTIONS = [
  {id:"g1",s:"The company's annual report _____ last week.",o:["published","was published","publishing","has publishing"],c:1,x:"Passive voice: The report was published (by someone).",cat:"Passive Voice"},
  {id:"g2",s:"Ms. Tanaka is _____ for managing the Tokyo office.",o:["responsible","responsibility","responsibly","respond"],c:0,x:"'Responsible' (adj) collocates with 'for'.",cat:"Word Families"},
  {id:"g3",s:"All employees must submit their timesheets _____ Friday.",o:["by","until","since","from"],c:0,x:"'By Friday' = no later than Friday (deadline).",cat:"Prepositions"},
  {id:"g4",s:"The new software is _____ more efficient than the previous version.",o:["considering","considerable","considerably","consideration"],c:2,x:"'Considerably' (adverb) modifies 'more efficient'.",cat:"Word Families"},
  {id:"g5",s:"_____ the heavy rain, the outdoor event proceeded as planned.",o:["Despite","Although","Because","However"],c:0,x:"'Despite' + noun phrase. 'Although' needs a clause.",cat:"Connectors"},
  {id:"g6",s:"The marketing team _____ on a new campaign since January.",o:["works","worked","has been working","is working"],c:2,x:"'Since January' = present perfect continuous.",cat:"Tenses"},
  {id:"g7",s:"Please ensure that all documents are filed _____.",o:["proper","properly","properness","more proper"],c:1,x:"'Properly' (adverb) modifies the verb 'are filed'.",cat:"Word Families"},
  {id:"g8",s:"Mr. Chen will attend the conference _____ he can finalize the partnership.",o:["so that","despite","unless","even though"],c:0,x:"'So that' expresses purpose.",cat:"Connectors"},
  {id:"g9",s:"The warranty _____ if the product is misused.",o:["voids","voided","will be voided","voiding"],c:2,x:"First conditional: will + be + past participle (passive).",cat:"Conditionals"},
  {id:"g10",s:"Each department head must submit a _____ budget proposal.",o:["detail","detailed","detailing","details"],c:1,x:"'Detailed' (adjective) modifies the noun 'budget proposal'.",cat:"Word Families"},
  {id:"g11",s:"The CEO, _____ with the board members, announced the merger.",o:["along","as well","together","both"],c:0,x:"'Along with' is the correct collocation.",cat:"Prepositions"},
  {id:"g12",s:"Applicants _____ meet all requirements will be contacted.",o:["who","which","whose","whom"],c:0,x:"'Who' = relative pronoun for people as subject.",cat:"Relative Pronouns"},
  {id:"g13",s:"The project was completed ahead of _____.",o:["schedule","scheduling","scheduled","schedules"],c:0,x:"'Ahead of schedule' = fixed expression.",cat:"Collocations"},
  {id:"g14",s:"_____ reviewing the contract, the lawyer found errors.",o:["While","During","For","Since"],c:0,x:"'While' + verb-ing for simultaneous actions.",cat:"Connectors"},
  {id:"g15",s:"The sales figures were _____ higher than projected.",o:["significance","significant","significantly","signify"],c:2,x:"'Significantly' (adverb) modifies 'higher'.",cat:"Word Families"},
  {id:"g16",s:"We need to hire someone _____ experience in data analysis.",o:["with","of","for","by"],c:0,x:"'Someone with experience' = possession of a quality.",cat:"Prepositions"},
  {id:"g17",s:"The factory _____ 10,000 units by the end of this month.",o:["produces","will have produced","produced","producing"],c:1,x:"'By the end of...' = future perfect.",cat:"Tenses"},
  {id:"g18",s:"_____ you have any questions, please contact us.",o:["Should","Would","Could","Might"],c:0,x:"'Should you have' = formal inversion of 'If you should have'.",cat:"Conditionals"},
  {id:"g19",s:"The report highlights the _____ of investing in renewable energy.",o:["important","importantly","importance","import"],c:2,x:"'Importance' (noun) follows 'the'.",cat:"Word Families"},
  {id:"g20",s:"Employees are encouraged to participate _____ the program.",o:["in","at","on","to"],c:0,x:"'Participate in' = correct collocation.",cat:"Prepositions"},
  {id:"g21",s:"The merger will _____ result in significant cost savings.",o:["like","likely","likeliness","alike"],c:1,x:"'Likely' (adverb) modifies the verb 'result'.",cat:"Word Families"},
  {id:"g22",s:"_____ the deadline has passed, no applications will be accepted.",o:["Although","Since","Despite","However"],c:1,x:"'Since' = because (causal connector) + clause.",cat:"Connectors"},
  {id:"g23",s:"The training session is _____ for all new employees.",o:["mandate","mandated","mandatory","mandating"],c:2,x:"'Mandatory' (adjective) after 'is'.",cat:"Word Families"},
  {id:"g24",s:"She has worked here _____ she graduated from university.",o:["for","since","during","while"],c:1,x:"'Since' + point in time. 'For' + duration.",cat:"Prepositions"},
  {id:"g25",s:"The list of candidates _____ been updated.",o:["have","has","are","is"],c:1,x:"Subject = 'list' (singular), not 'candidates'. The list HAS been updated.",cat:"Subject-Verb Agreement"},
  {id:"g26",s:"Each of the employees _____ required to attend the training.",o:["are","is","were","have"],c:1,x:"'Each' is always singular. Each of the employees IS required.",cat:"Subject-Verb Agreement"},
  {id:"g27",s:"Neither the manager nor the staff _____ available for comment.",o:["was","is","were","has"],c:2,x:"With 'neither...nor', the verb agrees with the CLOSEST subject ('staff' = plural).",cat:"Subject-Verb Agreement"},
  {id:"g28",s:"The number of complaints _____ decreased significantly.",o:["have","has","are","were"],c:1,x:"'The number of' = singular subject. HAS decreased. (vs 'A number of' = plural.)",cat:"Subject-Verb Agreement"},
  {id:"g29",s:"This model is _____ than the previous one.",o:["more efficient","most efficient","as efficient","efficiently"],c:0,x:"Comparative: more + adjective + THAN. 'Most' = superlative.",cat:"Comparatives"},
  {id:"g30",s:"This is the _____ product in our entire range.",o:["best-selling","better-selling","more selling","good-selling"],c:0,x:"Superlative: 'the' + best (irregular superlative of 'good').",cat:"Comparatives"},
  {id:"g31",s:"The sooner we start, the _____ we will finish.",o:["sooner","soonest","more soon","soon"],c:0,x:"Double comparative: 'The + comparative, the + comparative'. The sooner, the sooner.",cat:"Comparatives"},
  {id:"g32",s:"Our new office is _____ spacious as the old one.",o:["so","as","more","most"],c:1,x:"Equality comparison: as + adjective + AS. 'As spacious as'.",cat:"Comparatives"},
  {id:"g33",s:"The manager suggested _____ the meeting to next week.",o:["to postpone","postponing","postpone","postponed"],c:1,x:"'Suggest' takes a gerund (-ing). Suggest + postponing.",cat:"Gerunds vs Infinitives"},
  {id:"g34",s:"The team agreed _____ the deadline by two days.",o:["extending","to extend","extend","extended"],c:1,x:"'Agree' takes an infinitive (to). Agreed to extend.",cat:"Gerunds vs Infinitives"},
  {id:"g35",s:"We should consider _____ a consultant for this project.",o:["to hire","hiring","hire","hired"],c:1,x:"'Consider' always takes a gerund (-ing). Consider hiring.",cat:"Gerunds vs Infinitives"},
  {id:"g36",s:"He stopped _____ when the meeting began.",o:["to talk","talking","talk","talked"],c:1,x:"'Stop + -ing' = cease the action. He stopped talking (= he was talking, then stopped).",cat:"Gerunds vs Infinitives"},
  
  // ═══════════════════════════════════════════════════════════════
// BATCH 3 — NEW QUESTIONS (g201–g404) — 200 questions
// Paste these inside the QUESTIONS array in grammar.js
// (add a comma after the last existing entry, then paste)
// ═══════════════════════════════════════════════════════════════

  // ─── TENSES (g201–g217) ───
  {id:"g201",s:"The board _____ the restructuring plan at yesterday's meeting.",o:["approves","approved","has approved","is approving"],c:1,x:"'Yesterday's meeting' = specific past time → past simple.",cat:"Tenses"},
  {id:"g202",s:"By next quarter, we _____ all legacy systems to the cloud.",o:["migrate","will migrate","will have migrated","are migrating"],c:2,x:"'By next quarter' = future deadline → future perfect.",cat:"Tenses"},
  {id:"g203",s:"The customer service team _____ over 300 calls every day.",o:["is handling","handles","has handled","handled"],c:1,x:"'Every day' = routine/habitual → present simple.",cat:"Tenses"},
  {id:"g204",s:"When I called the office, Ms. Park _____ with a client.",o:["meets","met","was meeting","has met"],c:2,x:"Action in progress at a specific past moment → past continuous.",cat:"Tenses"},
  {id:"g205",s:"The company _____ three new branches since the beginning of the year.",o:["opens","opened","has opened","is opening"],c:2,x:"'Since the beginning of the year' = present perfect for action with present relevance.",cat:"Tenses"},
  {id:"g206",s:"Mr. Novak _____ in the finance department before he was promoted.",o:["works","has worked","had worked","is working"],c:2,x:"Action completed before another past event (promotion) → past perfect.",cat:"Tenses"},
  {id:"g207",s:"The flight to Seoul _____ at 6:45 AM tomorrow.",o:["departs","will depart","is departing","departed"],c:0,x:"Scheduled timetable event → present simple even for future.",cat:"Tenses"},
  {id:"g208",s:"Analysts predict that demand _____ sharply in the fourth quarter.",o:["rises","rose","will rise","has risen"],c:2,x:"Prediction about the future after 'predict that' → will + base verb.",cat:"Tenses"},
  {id:"g209",s:"Our legal team _____ the contract for two weeks now and still has concerns.",o:["reviews","reviewed","has been reviewing","had reviewed"],c:2,x:"'For two weeks now' = ongoing action from past to present → present perfect continuous.",cat:"Tenses"},
  {id:"g210",s:"Once the audit _____, we will release the financial report.",o:["is completed","will be completed","completed","has been completed"],c:0,x:"After 'once' (time clause), use present tense for future meaning.",cat:"Tenses"},
  {id:"g211",s:"Revenue _____ steadily since the new CEO took over.",o:["grows","grew","has grown","had grown"],c:2,x:"'Since + past event' with result visible now → present perfect.",cat:"Tenses"},
  {id:"g212",s:"At this time next Monday, the delegates _____ the keynote speech.",o:["attend","will attend","will be attending","have attended"],c:2,x:"'At this time next Monday' = action in progress at a future moment → future continuous.",cat:"Tenses"},
  {id:"g213",s:"The R&D department _____ a breakthrough just before the funding was cut.",o:["achieves","achieved","had achieved","has achieved"],c:2,x:"Action completed before another past event (funding cut) → past perfect.",cat:"Tenses"},
  {id:"g214",s:"The regional office _____ all operations to the headquarters last month.",o:["transfers","transferred","has transferred","is transferring"],c:1,x:"'Last month' = specific past time → past simple.",cat:"Tenses"},
  {id:"g215",s:"By the time you receive this memo, the policy _____ already _____.",o:["will … change","will … have changed","has … changed","is … changing"],c:1,x:"'By the time + present' → future perfect: will have changed.",cat:"Tenses"},
  {id:"g216",s:"The warehouse crew _____ inventory every Friday afternoon.",o:["counts","is counting","has counted","counted"],c:0,x:"'Every Friday' = regular routine → present simple.",cat:"Tenses"},
  {id:"g217",s:"Ms. Liu _____ the Singapore branch for five years when she retired.",o:["manages","managed","was managing","had been managing"],c:3,x:"Duration up to a past point ('for five years when she retired') → past perfect continuous.",cat:"Tenses"},

  // ─── PASSIVE VOICE (g218–g234) ───
  {id:"g218",s:"All expense reports must _____ by the end of the month.",o:["submit","be submitted","submitting","have submitting"],c:1,x:"Modal + passive: must + be + past participle.",cat:"Passive Voice"},
  {id:"g219",s:"The new policy _____ to all employees via email yesterday.",o:["communicated","was communicated","communicates","has communicated"],c:1,x:"The policy didn't communicate itself — it was communicated (by someone).",cat:"Passive Voice"},
  {id:"g220",s:"Candidates who _____ for the position will be contacted by Friday.",o:["are shortlisted","shortlist","shortlisting","have shortlisting"],c:0,x:"Candidates are shortlisted (by the recruiter) — passive with present tense.",cat:"Passive Voice"},
  {id:"g221",s:"The building _____ currently _____ to meet new safety standards.",o:["is … renovating","is … being renovated","has … renovated","was … renovating"],c:1,x:"Present continuous passive: is + being + past participle.",cat:"Passive Voice"},
  {id:"g222",s:"Over 5,000 units _____ before the defect was discovered.",o:["shipped","were shipped","have shipped","are shipping"],c:1,x:"Past passive before another past event. Units were shipped (by the warehouse).",cat:"Passive Voice"},
  {id:"g223",s:"Confidential documents should _____ in a secure location.",o:["store","be stored","storing","stored"],c:1,x:"Should + be + past participle. Documents are stored (by someone).",cat:"Passive Voice"},
  {id:"g224",s:"The annual report _____ by an independent auditor every year.",o:["reviews","reviewed","is reviewed","reviewing"],c:2,x:"'Every year' = habitual passive. The report is reviewed (by the auditor).",cat:"Passive Voice"},
  {id:"g225",s:"All safety equipment _____ thoroughly before it left the factory.",o:["tested","was tested","has tested","tests"],c:1,x:"Past simple passive: equipment was tested before leaving.",cat:"Passive Voice"},
  {id:"g226",s:"The merger is expected _____ completed by the end of this year.",o:["being","to be","be","been"],c:1,x:"'Is expected to be' = passive infinitive construction.",cat:"Passive Voice"},
  {id:"g227",s:"A new branch _____ in Dubai since last January.",o:["has been built","has built","is building","built"],c:0,x:"'Since last January' = present perfect passive. The branch has been built.",cat:"Passive Voice"},
  {id:"g228",s:"Employees are _____ to update their passwords every 90 days.",o:["requiring","required","require","requirement"],c:1,x:"Passive: Employees are required (by the policy). Past participle after 'are'.",cat:"Passive Voice"},
  {id:"g229",s:"The shipment could not _____ due to severe weather conditions.",o:["deliver","be delivered","delivering","delivered"],c:1,x:"Modal negative passive: could not + be + past participle.",cat:"Passive Voice"},
  {id:"g230",s:"Several complaints _____ about the new parking system.",o:["have been received","have received","are receiving","received"],c:0,x:"Complaints are received (by the company) — present perfect passive.",cat:"Passive Voice"},
  {id:"g231",s:"The event venue _____ decorated when the guests arrived.",o:["has been","had been","is being","will be"],c:1,x:"Past perfect passive: action completed before guests arrived.",cat:"Passive Voice"},
  {id:"g232",s:"Applications submitted after the deadline will not _____.",o:["consider","be considered","considering","considered"],c:1,x:"Future passive: will not + be + past participle.",cat:"Passive Voice"},
  {id:"g233",s:"The training materials _____ in both English and Spanish.",o:["are provided","provide","providing","provides"],c:0,x:"Materials are provided (by the company) — present simple passive.",cat:"Passive Voice"},
  {id:"g234",s:"The prototype needs _____ before mass production begins.",o:["to test","to be tested","testing","test"],c:1,x:"'Needs to be tested' = passive infinitive. The prototype doesn't test itself.",cat:"Passive Voice"},

  // ─── SUBJECT-VERB AGREEMENT (g235–g252) ───
  {id:"g235",s:"A variety of training programs _____ available to new hires.",o:["is","are","has","was"],c:1,x:"'A variety of + plural noun' takes plural verb. Programs ARE available.",cat:"Subject-Verb Agreement"},
  {id:"g236",s:"The equipment in both warehouses _____ been inspected.",o:["have","has","are","were"],c:1,x:"Subject = 'equipment' (uncountable, singular). Equipment HAS been inspected.",cat:"Subject-Verb Agreement"},
  {id:"g237",s:"Every employee and intern _____ expected to attend the orientation.",o:["are","is","were","have"],c:1,x:"'Every X and Y' = singular. Every employee IS expected.",cat:"Subject-Verb Agreement"},
  {id:"g238",s:"The results of the survey _____ quite surprising.",o:["was","is","were","has been"],c:2,x:"Subject = 'results' (plural). The results WERE surprising.",cat:"Subject-Verb Agreement"},
  {id:"g239",s:"Either the director or her assistants _____ going to handle it.",o:["is","are","was","has"],c:1,x:"'Either…or' — verb agrees with the nearest subject: 'assistants' (plural) → ARE.",cat:"Subject-Verb Agreement"},
  {id:"g240",s:"Ten thousand dollars _____ a reasonable budget for the event.",o:["are","is","were","have been"],c:1,x:"An amount of money treated as a single sum → singular verb. $10,000 IS reasonable.",cat:"Subject-Verb Agreement"},
  {id:"g241",s:"The information provided in these documents _____ confidential.",o:["are","is","were","have been"],c:1,x:"'Information' = uncountable → singular. Information IS confidential.",cat:"Subject-Verb Agreement"},
  {id:"g242",s:"Not only the manager but also the team members _____ responsible.",o:["is","was","are","has been"],c:2,x:"'Not only…but also' — verb agrees with nearest subject: 'members' (plural) → ARE.",cat:"Subject-Verb Agreement"},
  {id:"g243",s:"None of the merchandise _____ arrived at the store yet.",o:["have","has","are","were"],c:1,x:"'None of' + uncountable noun → singular. Merchandise HAS arrived.",cat:"Subject-Verb Agreement"},
  {id:"g244",s:"A number of clients _____ expressed interest in the new service.",o:["has","is","have","was"],c:2,x:"'A number of' = many → plural verb. Clients HAVE expressed.",cat:"Subject-Verb Agreement"},
  {id:"g245",s:"The CEO, along with several executives, _____ visiting the plant today.",o:["are","is","were","have been"],c:1,x:"'Along with' doesn't change the subject. Subject = CEO (singular) → IS visiting.",cat:"Subject-Verb Agreement"},
  {id:"g246",s:"There _____ several issues that need to be addressed.",o:["is","has","are","was"],c:2,x:"'There are' + plural noun. Several issues → ARE.",cat:"Subject-Verb Agreement"},
  {id:"g247",s:"Five hours _____ enough time to complete the assessment.",o:["are","is","were","have been"],c:1,x:"A period of time as a single unit → singular. Five hours IS enough.",cat:"Subject-Verb Agreement"},
  {id:"g248",s:"Half of the budget _____ already been allocated.",o:["have","has","were","are"],c:1,x:"'Half of the budget' — budget is singular/uncountable → HAS been allocated.",cat:"Subject-Verb Agreement"},
  {id:"g249",s:"The staff _____ divided on the issue of remote work.",o:["is","are","was","has"],c:1,x:"'Staff' as a group with differing opinions → singular 'is' (BrE allows 'are', but TOEIC prefers singular for collective nouns).",cat:"Subject-Verb Agreement"},
  {id:"g250",s:"One of the machines on the factory floor _____ malfunctioning.",o:["are","have been","is","were"],c:2,x:"'One of' = singular subject. One IS malfunctioning.",cat:"Subject-Verb Agreement"},
  {id:"g251",s:"The news about the layoffs _____ shocked everyone.",o:["have","has","are","were"],c:1,x:"'News' = uncountable, always singular. The news HAS shocked.",cat:"Subject-Verb Agreement"},
  {id:"g252",s:"Physics _____ a required course for all engineering students.",o:["are","were","is","have been"],c:2,x:"Academic subjects ending in -s (physics, economics) → singular. Physics IS required.",cat:"Subject-Verb Agreement"},

  // ─── WORD FAMILIES (g253–g270) ───
  {id:"g253",s:"The company has made a _____ investment in green technology.",o:["substance","substantial","substantially","substantiate"],c:1,x:"Adjective before noun: 'a substantial investment'.",cat:"Word Families"},
  {id:"g254",s:"Customer feedback was _____ positive after the product launch.",o:["overwhelm","overwhelming","overwhelmingly","overwhelmed"],c:2,x:"Adverb modifies adjective 'positive': overwhelmingly positive.",cat:"Word Families"},
  {id:"g255",s:"The _____ of the new safety regulations took several months.",o:["develop","developed","developing","development"],c:3,x:"'The _____ of' = noun needed. 'The development of'.",cat:"Word Families"},
  {id:"g256",s:"Please handle this matter with the utmost _____.",o:["discreet","discretion","discreetly","discrete"],c:1,x:"'With' + noun. 'With discretion'. Note: discreet ≠ discrete.",cat:"Word Families"},
  {id:"g257",s:"It is _____ important that we meet the deadline.",o:["extreme","extremity","extremely","extremism"],c:2,x:"Adverb modifies adjective 'important': extremely important.",cat:"Word Families"},
  {id:"g258",s:"The _____ of the two proposals revealed significant differences.",o:["compare","comparison","comparable","comparatively"],c:1,x:"'The _____ of' = noun. 'The comparison of'.",cat:"Word Families"},
  {id:"g259",s:"We are looking for a candidate with strong _____ skills.",o:["analysis","analytical","analytically","analyze"],c:1,x:"Adjective before noun: 'analytical skills'.",cat:"Word Families"},
  {id:"g260",s:"The factory operates _____ around the clock.",o:["continue","continuous","continuously","continuation"],c:2,x:"Adverb modifies verb 'operates': operates continuously.",cat:"Word Families"},
  {id:"g261",s:"The marketing team presented a _____ strategy for the new product.",o:["comprehend","comprehensive","comprehensively","comprehension"],c:1,x:"Adjective before noun: 'a comprehensive strategy'.",cat:"Word Families"},
  {id:"g262",s:"Mr. Torres received official _____ that his transfer was approved.",o:["confirm","confirmation","confirmed","confirmatory"],c:1,x:"Adjective 'official' + noun: 'official confirmation'.",cat:"Word Families"},
  {id:"g263",s:"The report should be written as _____ as possible.",o:["concise","concisely","conciseness","concision"],c:1,x:"'As _____ as possible' with 'written' = adverb. 'As concisely as possible'.",cat:"Word Families"},
  {id:"g264",s:"All participants must provide _____ identification before entering.",o:["validity","valid","validate","validly"],c:1,x:"Adjective before noun: 'valid identification'.",cat:"Word Families"},
  {id:"g265",s:"The company prides itself on the _____ of its workforce.",o:["diverse","diversely","diversify","diversity"],c:3,x:"'The _____ of' = noun needed. 'The diversity of'.",cat:"Word Families"},
  {id:"g266",s:"The new regulations have been _____ enforced since April.",o:["strict","strictly","strictness","stricter"],c:1,x:"Adverb modifies past participle 'enforced': strictly enforced.",cat:"Word Families"},
  {id:"g267",s:"Her _____ performance earned her a promotion.",o:["exception","exceptional","exceptionally","except"],c:1,x:"Adjective before noun: 'exceptional performance'.",cat:"Word Families"},
  {id:"g268",s:"The _____ of raw materials has increased by 12%.",o:["avail","availability","available","availably"],c:1,x:"'The _____ of' = noun. 'The availability of'.",cat:"Word Families"},
  {id:"g269",s:"Negotiations between the two firms are progressing _____.",o:["favor","favorable","favorably","favored"],c:2,x:"Adverb modifies verb 'are progressing': progressing favorably.",cat:"Word Families"},
  {id:"g270",s:"The CEO issued a _____ apology to shareholders.",o:["person","personally","personal","personalize"],c:2,x:"Adjective before noun: 'a personal apology'.",cat:"Word Families"},

  // ─── CONNECTORS (g271–g288) ───
  {id:"g271",s:"The product launch was delayed _____ unforeseen supply chain issues.",o:["because","due to","although","so that"],c:1,x:"'Due to' + noun phrase. 'Because' needs a clause (because + subject + verb).",cat:"Connectors"},
  {id:"g272",s:"_____ the project was over budget, the results exceeded expectations.",o:["Despite","Even though","Because of","Due to"],c:1,x:"'Even though' + clause. 'Despite/Because of' + noun phrase.",cat:"Connectors"},
  {id:"g273",s:"Ms. Nakamura was promoted _____ her outstanding sales record.",o:["although","in spite of","thanks to","even though"],c:2,x:"'Thanks to' = because of (positive cause) + noun phrase.",cat:"Connectors"},
  {id:"g274",s:"The office will remain open _____ the renovation is completed.",o:["until","by","since","for"],c:0,x:"'Until' = up to the point when. The office stays open until completion.",cat:"Connectors"},
  {id:"g275",s:"_____ you agree to the terms, please sign at the bottom of the page.",o:["Unless","If","Although","Despite"],c:1,x:"'If you agree' = conditional. 'Unless' would reverse the meaning.",cat:"Connectors"},
  {id:"g276",s:"The proposal was rejected; _____, the team submitted a revised version.",o:["therefore","however","moreover","furthermore"],c:1,x:"'However' = contrast connector. Rejection → but they tried again.",cat:"Connectors"},
  {id:"g277",s:"Prices will increase _____ demand continues to grow.",o:["unless","as long as","so that","in order to"],c:1,x:"'As long as' = on the condition that. Prices rise if demand grows.",cat:"Connectors"},
  {id:"g278",s:"The new policy benefits employees _____ reducing company costs.",o:["while","during","despite","although"],c:0,x:"'While' + verb-ing = simultaneous/contrastive. While reducing costs.",cat:"Connectors"},
  {id:"g279",s:"The seminar was postponed _____ the speaker's sudden illness.",o:["because","owing to","although","whereas"],c:1,x:"'Owing to' + noun phrase = because of.",cat:"Connectors"},
  {id:"g280",s:"_____ the economy recovers, unemployment rates should decrease.",o:["Once","Despite","Even","Unless"],c:0,x:"'Once' = as soon as / when. Once it recovers → rates decrease.",cat:"Connectors"},
  {id:"g281",s:"The company invested in automation; _____, it hired more IT staff.",o:["however","in addition","otherwise","instead"],c:1,x:"'In addition' = also/moreover. Two complementary actions.",cat:"Connectors"},
  {id:"g282",s:"The report must be reviewed _____ it can be published.",o:["before","while","since","during"],c:0,x:"'Before' = prior to. Review happens first, then publication.",cat:"Connectors"},
  {id:"g283",s:"We expanded into Asia _____ increase our market share.",o:["in order to","so that","due to","because"],c:0,x:"'In order to' + base verb = purpose. 'So that' needs a clause.",cat:"Connectors"},
  {id:"g284",s:"Profits declined last quarter; _____, the company remains optimistic.",o:["therefore","furthermore","nevertheless","consequently"],c:2,x:"'Nevertheless' = despite that. Contrast between decline and optimism.",cat:"Connectors"},
  {id:"g285",s:"_____ the instructions carefully before assembling the product.",o:["Read","Reading","Having read","To read"],c:0,x:"Imperative sentence (command): base verb 'Read' at the start.",cat:"Connectors"},
  {id:"g286",s:"The warranty is valid _____ the product is used according to guidelines.",o:["provided that","despite","although","in spite of"],c:0,x:"'Provided that' = on the condition that. Warranty valid if used correctly.",cat:"Connectors"},
  {id:"g287",s:"Production has increased; _____, quality has not been compromised.",o:["yet","so","for","nor"],c:0,x:"'Yet' = but/however. Contrast: more production but quality maintained.",cat:"Connectors"},
  {id:"g288",s:"_____ having limited resources, the team delivered on time.",o:["Despite","Although","Because of","Since"],c:0,x:"'Despite' + gerund phrase. 'Although' would need a full clause.",cat:"Connectors"},

  // ─── PREPOSITIONS (g289–g306) ───
  {id:"g289",s:"The conference will be held _____ May 12th and 14th.",o:["from","between","during","within"],c:1,x:"'Between' + two specific dates. Between May 12th and 14th.",cat:"Prepositions"},
  {id:"g290",s:"The company specializes _____ renewable energy solutions.",o:["at","on","in","for"],c:2,x:"'Specialize in' = correct collocation.",cat:"Prepositions"},
  {id:"g291",s:"Please refrain _____ using mobile phones during the presentation.",o:["of","from","to","with"],c:1,x:"'Refrain from' + gerund = correct collocation.",cat:"Prepositions"},
  {id:"g292",s:"The new regulation applies _____ all financial institutions.",o:["for","on","to","with"],c:2,x:"'Apply to' = be relevant to. Applies to all institutions.",cat:"Prepositions"},
  {id:"g293",s:"We must comply _____ the new data protection laws.",o:["to","by","with","for"],c:2,x:"'Comply with' = follow/adhere to. Comply with the laws.",cat:"Prepositions"},
  {id:"g294",s:"The team was praised _____ its exceptional performance.",o:["about","for","on","to"],c:1,x:"'Praised for' = reason for praise. Praised for performance.",cat:"Prepositions"},
  {id:"g295",s:"Sales increased _____ 20% compared to the previous quarter.",o:["for","with","by","at"],c:2,x:"'Increase by' + amount/percentage. Increased by 20%.",cat:"Prepositions"},
  {id:"g296",s:"The meeting has been rescheduled _____ Thursday.",o:["in","on","at","by"],c:1,x:"'On' + day of the week. Rescheduled on Thursday.",cat:"Prepositions"},
  {id:"g297",s:"The manager insisted _____ reviewing all the documents personally.",o:["in","on","for","to"],c:1,x:"'Insist on' + gerund = correct collocation.",cat:"Prepositions"},
  {id:"g298",s:"The success of the project depends _____ several factors.",o:["to","from","on","for"],c:2,x:"'Depend on' = correct collocation.",cat:"Prepositions"},
  {id:"g299",s:"We apologize _____ any inconvenience caused by the delay.",o:["about","on","with","for"],c:3,x:"'Apologize for' = correct collocation.",cat:"Prepositions"},
  {id:"g300",s:"The office is located _____ the corner of Main Street and 5th Avenue.",o:["in","on","at","by"],c:2,x:"'At the corner of' = specific point/intersection.",cat:"Prepositions"},
  {id:"g301",s:"Mr. Santos is responsible _____ overseeing the logistics department.",o:["of","for","to","about"],c:1,x:"'Responsible for' + gerund = correct collocation.",cat:"Prepositions"},
  {id:"g302",s:"The decrease in sales was attributed _____ poor marketing.",o:["for","with","to","by"],c:2,x:"'Attributed to' = caused by. Attributed to poor marketing.",cat:"Prepositions"},
  {id:"g303",s:"All purchases are subject _____ a 10% handling fee.",o:["for","with","of","to"],c:3,x:"'Subject to' = liable to. Subject to a fee.",cat:"Prepositions"},
  {id:"g304",s:"The interns reported directly _____ the head of marketing.",o:["at","for","to","with"],c:2,x:"'Report to' someone = work under someone's supervision.",cat:"Prepositions"},
  {id:"g305",s:"We are confident _____ the quality of our products.",o:["on","in","for","at"],c:1,x:"'Confident in' = trust in. Confident in the quality.",cat:"Prepositions"},
  {id:"g306",s:"The deadline was extended _____ one additional week.",o:["for","in","at","on"],c:0,x:"'Extended for' + duration. Extended for one week.",cat:"Prepositions"},

  // ─── GERUNDS VS INFINITIVES (g307–g323) ───
  {id:"g307",s:"The board decided _____ the merger until next year.",o:["postponing","to postpone","postpone","having postponed"],c:1,x:"'Decide' takes infinitive (to). Decided to postpone.",cat:"Gerunds vs Infinitives"},
  {id:"g308",s:"We appreciate your _____ the time to complete the survey.",o:["take","to take","taking","taken"],c:2,x:"'Appreciate' + possessive + gerund. Appreciate your taking the time.",cat:"Gerunds vs Infinitives"},
  {id:"g309",s:"The company cannot afford _____ any more staff at this time.",o:["hiring","to hire","hire","having hired"],c:1,x:"'Afford' takes infinitive (to). Cannot afford to hire.",cat:"Gerunds vs Infinitives"},
  {id:"g310",s:"Employees should avoid _____ confidential information over email.",o:["to share","share","sharing","shared"],c:2,x:"'Avoid' always takes gerund (-ing). Avoid sharing.",cat:"Gerunds vs Infinitives"},
  {id:"g311",s:"The CEO encouraged all staff _____ in the wellness program.",o:["participating","to participate","participate","participated"],c:1,x:"'Encourage someone to do' = infinitive. Encouraged staff to participate.",cat:"Gerunds vs Infinitives"},
  {id:"g312",s:"Ms. Patel denied _____ access to the restricted files.",o:["to have","having","have","to having"],c:1,x:"'Deny' takes gerund. Denied having access.",cat:"Gerunds vs Infinitives"},
  {id:"g313",s:"The manual explains how _____ the software correctly.",o:["installing","to install","install","installed"],c:1,x:"'How to + base verb' = infinitive. How to install.",cat:"Gerunds vs Infinitives"},
  {id:"g314",s:"We look forward to _____ from you soon.",o:["hear","hearing","heard","have heard"],c:1,x:"'Look forward to' + gerund. 'To' here is a preposition, not infinitive marker.",cat:"Gerunds vs Infinitives"},
  {id:"g315",s:"The consultant recommended _____ the budget by 15%.",o:["to increase","increasing","increase","increased"],c:1,x:"'Recommend' takes gerund. Recommended increasing.",cat:"Gerunds vs Infinitives"},
  {id:"g316",s:"They attempted _____ the server issue before the morning shift.",o:["fixing","to fix","fix","fixed"],c:1,x:"'Attempt' takes infinitive (to). Attempted to fix.",cat:"Gerunds vs Infinitives"},
  {id:"g317",s:"The new regulations require employees _____ a security badge at all times.",o:["wearing","to wear","wear","worn"],c:1,x:"'Require someone to do' = infinitive. Require employees to wear.",cat:"Gerunds vs Infinitives"},
  {id:"g318",s:"He admitted _____ the error in the financial report.",o:["to make","making","make","to making"],c:1,x:"'Admit' takes gerund. Admitted making the error.",cat:"Gerunds vs Infinitives"},
  {id:"g319",s:"The training program is designed _____ improve communication skills.",o:["for","to","at","in"],c:1,x:"'Designed to + base verb' = purpose infinitive.",cat:"Gerunds vs Infinitives"},
  {id:"g320",s:"Would you mind _____ the door? It's getting cold in here.",o:["to close","close","closing","closed"],c:2,x:"'Would you mind' + gerund. Mind closing.",cat:"Gerunds vs Infinitives"},
  {id:"g321",s:"The client expects _____ a full refund within 30 days.",o:["receiving","to receive","receive","received"],c:1,x:"'Expect' takes infinitive (to). Expects to receive.",cat:"Gerunds vs Infinitives"},
  {id:"g322",s:"She keeps _____ the same mistake in her reports.",o:["to make","make","making","made"],c:2,x:"'Keep' + gerund = continue doing. Keeps making.",cat:"Gerunds vs Infinitives"},
  {id:"g323",s:"The committee agreed _____ the proposal with minor changes.",o:["accepting","to accept","accept","accepted"],c:1,x:"'Agree' takes infinitive (to). Agreed to accept.",cat:"Gerunds vs Infinitives"},

  // ─── CONDITIONALS (g324–g340) ───
  {id:"g324",s:"If demand _____, we will need to increase production capacity.",o:["rise","rises","will rise","would rise"],c:1,x:"First conditional: If + present simple, will + base verb.",cat:"Conditionals"},
  {id:"g325",s:"If I _____ more time, I would review the report again.",o:["have","has","had","will have"],c:2,x:"Second conditional: If + past simple, would + base verb. Hypothetical present.",cat:"Conditionals"},
  {id:"g326",s:"The project would have succeeded if the team _____ more resources.",o:["has","had","had had","would have"],c:2,x:"Third conditional: If + past perfect, would have + past participle. Unreal past.",cat:"Conditionals"},
  {id:"g327",s:"_____ the CEO resign, the board would appoint an interim leader.",o:["Should","Would","Could","Will"],c:0,x:"'Should' = formal inversion of 'If the CEO should resign'. Hypothetical future.",cat:"Conditionals"},
  {id:"g328",s:"Unless the supplier _____ the price, we will look for alternatives.",o:["lowers","lowered","will lower","would lower"],c:0,x:"'Unless' + present simple = 'if…not'. Same rule as first conditional.",cat:"Conditionals"},
  {id:"g329",s:"If we had invested earlier, we _____ much higher returns now.",o:["will have","would have","would have had","had"],c:1,x:"Mixed conditional: past condition → present result. Would have (now).",cat:"Conditionals"},
  {id:"g330",s:"Provided that the funds _____ available, construction will begin in May.",o:["are","were","will be","would be"],c:0,x:"'Provided that' + present tense for real/likely condition.",cat:"Conditionals"},
  {id:"g331",s:"If the delivery _____ delayed, please notify the customer immediately.",o:["is","was","will be","would be"],c:0,x:"First conditional/imperative: If + present simple, imperative.",cat:"Conditionals"},
  {id:"g332",s:"Had we known about the issue sooner, we _____ corrective action.",o:["take","took","would take","would have taken"],c:3,x:"Third conditional inversion: Had we known → would have taken.",cat:"Conditionals"},
  {id:"g333",s:"If the weather _____ good tomorrow, the event will be held outdoors.",o:["is","was","will be","were"],c:0,x:"First conditional: If + present simple for likely future events.",cat:"Conditionals"},
  {id:"g334",s:"If I _____ you, I would accept the offer immediately.",o:["am","was","were","will be"],c:2,x:"Second conditional: 'If I were you' (subjunctive — 'were' for all persons).",cat:"Conditionals"},
  {id:"g335",s:"We would not have lost the contract if we _____ a lower bid.",o:["submit","submitted","had submitted","would submit"],c:2,x:"Third conditional: If + past perfect. Had submitted → would not have lost.",cat:"Conditionals"},
  {id:"g336",s:"Employees may work from home _____ they meet their deadlines.",o:["unless","as long as","even if","in case"],c:1,x:"'As long as' = on the condition that. Conditional permission.",cat:"Conditionals"},
  {id:"g337",s:"If the software _____ properly, restart the computer.",o:["doesn't work","didn't work","won't work","wouldn't work"],c:0,x:"Zero/first conditional + imperative: If + present simple, command.",cat:"Conditionals"},
  {id:"g338",s:"_____ I in your position, I would negotiate a higher salary.",o:["Was","Were","Am","Would"],c:1,x:"Subjunctive inversion: 'Were I in your position' = If I were.",cat:"Conditionals"},
  {id:"g339",s:"If the order _____ by noon, it will be delivered the same day.",o:["places","is placed","will be placed","was placed"],c:1,x:"First conditional passive: If + present passive, will + base verb.",cat:"Conditionals"},
  {id:"g340",s:"We would expand overseas if we _____ sufficient capital.",o:["have","has","had","will have"],c:2,x:"Second conditional: If + past simple. Hypothetical — we don't have the capital.",cat:"Conditionals"},

  // ─── COMPARATIVES (g341–g357) ───
  {id:"g341",s:"This year's sales figures are _____ impressive than last year's.",o:["more","most","much","many"],c:0,x:"Comparative: more + adjective + than.",cat:"Comparatives"},
  {id:"g342",s:"The new model is by far the _____ option available.",o:["cheaper","cheapest","cheap","more cheap"],c:1,x:"Superlative: 'the + -est'. 'By far' emphasizes the superlative.",cat:"Comparatives"},
  {id:"g343",s:"The workshop lasted _____ longer than we had anticipated.",o:["many","much","more","most"],c:1,x:"'Much' intensifies comparatives: much longer, much better, much more.",cat:"Comparatives"},
  {id:"g344",s:"Our customer satisfaction rating is the _____ in the industry.",o:["higher","highest","high","highly"],c:1,x:"Superlative: 'the highest in' (comparing within a group).",cat:"Comparatives"},
  {id:"g345",s:"The second proposal was _____ detailed as the first one.",o:["so","as","more","most"],c:1,x:"Equality: as + adjective + as. As detailed as.",cat:"Comparatives"},
  {id:"g346",s:"The more employees we train, the _____ our service becomes.",o:["good","better","best","well"],c:1,x:"Double comparative: 'The more…, the better'. Parallel structure.",cat:"Comparatives"},
  {id:"g347",s:"This quarter's profits are slightly _____ than the previous quarter's.",o:["low","lower","lowest","lowly"],c:1,x:"Comparative + than: 'slightly lower than'. 'Slightly' modifies the comparative.",cat:"Comparatives"},
  {id:"g348",s:"Of the three candidates, Mr. Kim has the _____ relevant experience.",o:["more","most","much","very"],c:1,x:"Three or more = superlative. 'The most relevant'.",cat:"Comparatives"},
  {id:"g349",s:"Working from home is _____ less stressful than commuting daily.",o:["very","far","more","most"],c:1,x:"'Far' intensifies comparatives: far less, far better, far more.",cat:"Comparatives"},
  {id:"g350",s:"The _____ the deadline approaches, the harder the team works.",o:["close","closer","closest","closely"],c:1,x:"Double comparative: 'The closer…the harder'. Comparative form needed.",cat:"Comparatives"},
  {id:"g351",s:"This software is no _____ difficult to use than the previous version.",o:["much","more","most","very"],c:1,x:"'No more…than' = not any more difficult. Negative comparative.",cat:"Comparatives"},
  {id:"g352",s:"The express delivery option is considerably _____ than standard shipping.",o:["expensive","more expensive","most expensive","expensively"],c:1,x:"Two-syllable+ adjective: 'more expensive than'. 'Considerably' = adverb intensifier.",cat:"Comparatives"},
  {id:"g353",s:"She is one of the _____ qualified candidates we have interviewed.",o:["more","most","much","very"],c:1,x:"'One of the most + adjective' = superlative structure.",cat:"Comparatives"},
  {id:"g354",s:"The later model performs _____ than the original.",o:["efficient","efficiently","more efficiently","most efficiently"],c:2,x:"Comparing two items with an adverb: 'more efficiently than'.",cat:"Comparatives"},
  {id:"g355",s:"Tokyo is one of the _____ cities in the world for public transport.",o:["good","better","best","well"],c:2,x:"Superlative: 'one of the best'. Irregular: good → better → best.",cat:"Comparatives"},
  {id:"g356",s:"The CEO's speech was _____ inspiring than the one he gave last year.",o:["lesser","fewer","less","least"],c:2,x:"Negative comparative: 'less inspiring than'. 'Fewer' = countable only.",cat:"Comparatives"},
  {id:"g357",s:"This is the _____ complicated procedure in the entire manual.",o:["less","more","least","fewer"],c:2,x:"Superlative negative: 'the least complicated' = the simplest.",cat:"Comparatives"},

  // ─── RELATIVE PRONOUNS (g358–g374) ───
  {id:"g358",s:"The consultant _____ we hired last month has already made an impact.",o:["who","whom","whose","which"],c:1,x:"'Whom' = object of 'we hired'. We hired whom (formal). 'Who' also accepted in modern English.",cat:"Relative Pronouns"},
  {id:"g359",s:"The warehouse _____ stores our inventory is being renovated.",o:["who","where","which","whose"],c:2,x:"'Which' for things as subject: the warehouse which stores.",cat:"Relative Pronouns"},
  {id:"g360",s:"Ms. Garcia, _____ department won the award, will give a speech.",o:["who","whom","whose","which"],c:2,x:"'Whose' = possessive. Her department → whose department.",cat:"Relative Pronouns"},
  {id:"g361",s:"The day _____ the merger was announced, stock prices soared.",o:["which","when","where","whose"],c:1,x:"'When' for time references. The day when.",cat:"Relative Pronouns"},
  {id:"g362",s:"The building _____ our head office is located was built in 1920.",o:["which","that","where","when"],c:2,x:"'Where' = in which. The building where our office is located.",cat:"Relative Pronouns"},
  {id:"g363",s:"Employees _____ performance exceeds expectations will receive a bonus.",o:["who","whose","whom","which"],c:1,x:"'Whose' = possessive. Their performance → whose performance.",cat:"Relative Pronouns"},
  {id:"g364",s:"The proposal _____ was submitted last week has been approved.",o:["who","whose","that","whom"],c:2,x:"'That' for things as subject (defining clause). The proposal that was submitted.",cat:"Relative Pronouns"},
  {id:"g365",s:"The clients _____ we met at the trade show placed a large order.",o:["who","whom","whose","which"],c:1,x:"Object of 'we met' → whom/who. We met whom at the show.",cat:"Relative Pronouns"},
  {id:"g366",s:"The reason _____ the shipment was delayed has not been explained.",o:["which","why","when","where"],c:1,x:"'Why' after 'the reason'. The reason why it was delayed.",cat:"Relative Pronouns"},
  {id:"g367",s:"Mr. Lee, _____ joined the company in 2019, has been promoted.",o:["which","whom","whose","who"],c:3,x:"'Who' for people as subject (non-defining clause). Mr. Lee, who joined.",cat:"Relative Pronouns"},
  {id:"g368",s:"The internship program, _____ has been running for ten years, is very popular.",o:["who","that","which","whose"],c:2,x:"'Which' in non-defining clauses (with commas). 'That' cannot be used with commas.",cat:"Relative Pronouns"},
  {id:"g369",s:"The city _____ the annual conference takes place changes every year.",o:["which","where","when","whose"],c:1,x:"'Where' = in which. The city where the conference takes place.",cat:"Relative Pronouns"},
  {id:"g370",s:"Anyone _____ wishes to attend the training should register online.",o:["whom","whose","which","who"],c:3,x:"'Who' for people as subject. Anyone who wishes.",cat:"Relative Pronouns"},
  {id:"g371",s:"The software, _____ price has increased by 20%, remains popular.",o:["which","that","whose","whom"],c:2,x:"'Whose' = possessive, even for things. Its price → whose price.",cat:"Relative Pronouns"},
  {id:"g372",s:"The hotel _____ we stayed during the conference was excellent.",o:["where","which","whose","who"],c:0,x:"'Where' = at which. The hotel where we stayed.",cat:"Relative Pronouns"},
  {id:"g373",s:"This is the candidate _____ résumé impressed the hiring committee.",o:["who","whom","whose","which"],c:2,x:"Possessive: the candidate's résumé → whose résumé.",cat:"Relative Pronouns"},
  {id:"g374",s:"The manager to _____ I reported has retired.",o:["who","whom","that","which"],c:1,x:"After a preposition: 'to whom'. Formal relative pronoun.",cat:"Relative Pronouns"},

  // ─── COLLOCATIONS (g375–g391) ───
  {id:"g375",s:"The company needs to _____ a decision by the end of the week.",o:["do","take","make","have"],c:2,x:"'Make a decision' = fixed collocation.",cat:"Collocations"},
  {id:"g376",s:"We should _____ advantage of the early-bird discount.",o:["make","take","get","have"],c:1,x:"'Take advantage of' = fixed collocation.",cat:"Collocations"},
  {id:"g377",s:"The new initiative aims to _____ awareness about cybersecurity.",o:["rise","raise","grow","lift"],c:1,x:"'Raise awareness' = fixed collocation. 'Rise' is intransitive.",cat:"Collocations"},
  {id:"g378",s:"The CEO _____ a speech at the annual shareholders' meeting.",o:["told","said","gave","spoke"],c:2,x:"'Give a speech' = fixed collocation.",cat:"Collocations"},
  {id:"g379",s:"We need to _____ an appointment with the supplier as soon as possible.",o:["do","make","take","fix"],c:1,x:"'Make an appointment' = fixed collocation.",cat:"Collocations"},
  {id:"g380",s:"The marketing team _____ research on consumer preferences.",o:["made","did","conducted","performed"],c:2,x:"'Conduct research' = formal collocation. 'Do research' is also acceptable.",cat:"Collocations"},
  {id:"g381",s:"It is important to _____ attention to the terms and conditions.",o:["give","make","pay","take"],c:2,x:"'Pay attention to' = fixed collocation.",cat:"Collocations"},
  {id:"g382",s:"The company plans to _____ business in several new markets.",o:["make","do","conduct","perform"],c:1,x:"'Do business' = fixed collocation. Do business in new markets.",cat:"Collocations"},
  {id:"g383",s:"Mr. Yamada _____ a significant contribution to the project.",o:["did","made","gave","took"],c:1,x:"'Make a contribution' = fixed collocation.",cat:"Collocations"},
  {id:"g384",s:"The committee will _____ a meeting to discuss the proposal.",o:["make","do","hold","give"],c:2,x:"'Hold a meeting' = fixed collocation.",cat:"Collocations"},
  {id:"g385",s:"The new hire _____ a very good impression on the team.",o:["did","made","gave","took"],c:1,x:"'Make an impression' = fixed collocation.",cat:"Collocations"},
  {id:"g386",s:"We need to _____ measures to improve workplace safety.",o:["make","do","take","give"],c:2,x:"'Take measures' = fixed collocation. Take measures to improve.",cat:"Collocations"},
  {id:"g387",s:"The company _____ a loss of $2 million in the third quarter.",o:["made","suffered","did","gave"],c:1,x:"'Suffer a loss' = collocation for financial loss.",cat:"Collocations"},
  {id:"g388",s:"We expect to _____ significant progress by year-end.",o:["do","make","take","give"],c:1,x:"'Make progress' = fixed collocation.",cat:"Collocations"},
  {id:"g389",s:"It is essential that we _____ priority to customer satisfaction.",o:["make","do","take","give"],c:3,x:"'Give priority to' = fixed collocation.",cat:"Collocations"},
  {id:"g390",s:"The board _____ approval for the construction of a new facility.",o:["made","gave","took","did"],c:1,x:"'Give approval' = fixed collocation.",cat:"Collocations"},
  {id:"g391",s:"The firm has _____ a reputation for excellent customer service.",o:["done","made","built","taken"],c:2,x:"'Build a reputation' = collocation. You build a reputation over time.",cat:"Collocations"},

  // ─── ARTICLES (g392–g408) ───
  {id:"g392",s:"We need to find _____ solution to this problem as soon as possible.",o:["a","an","the","some"],c:0,x:"'A solution' — non-specific, one of many possible solutions.",cat:"Articles"},
  {id:"g393",s:"_____ CEO of GlobalTech announced her resignation this morning.",o:["A","An","The","No article"],c:2,x:"'The CEO of' = specific, identified person. Definite article.",cat:"Articles"},
  {id:"g394",s:"She has _____ MBA from a prestigious university.",o:["a","an","the","no article"],c:1,x:"'An MBA' — 'M' is pronounced /em/ (vowel sound) → 'an'.",cat:"Articles"},
  {id:"g395",s:"_____ honesty is the best policy when dealing with clients.",o:["A","An","The","No article"],c:3,x:"Abstract/general concept = no article. Honesty (in general).",cat:"Articles"},
  {id:"g396",s:"Could you please turn off _____ lights before leaving the office?",o:["a","an","the","some"],c:2,x:"'The lights' = specific lights (in this office). Definite article.",cat:"Articles"},
  {id:"g397",s:"Mr. Tanaka is _____ experienced negotiator.",o:["a","an","the","no article"],c:1,x:"'An experienced' — 'experienced' starts with a vowel sound → 'an'.",cat:"Articles"},
  {id:"g398",s:"_____ United Kingdom is one of our largest export markets.",o:["A","An","The","No article"],c:2,x:"Country names with 'Kingdom/States/Republic' take 'the'.",cat:"Articles"},
  {id:"g399",s:"We received _____ useful feedback from the focus group.",o:["a","an","some","the"],c:2,x:"'Feedback' is uncountable — no 'a/an'. 'Some' works. 'Useful' starts with /juː/ (consonant sound).",cat:"Articles"},
  {id:"g400",s:"_____ unemployment rate has fallen to its lowest level in a decade.",o:["A","An","The","No article"],c:2,x:"'The unemployment rate' = specific, unique metric. Definite article.",cat:"Articles"},
  {id:"g401",s:"She was appointed _____ chairperson of the committee.",o:["a","an","the","no article"],c:3,x:"Titles/roles after 'appointed/elected/named' = no article. Appointed chairperson.",cat:"Articles"},
  {id:"g402",s:"We hold meetings on _____ first Monday of every month.",o:["a","an","the","no article"],c:2,x:"Ordinal numbers take 'the': the first, the second, the third.",cat:"Articles"},
  {id:"g403",s:"_____ water damage to the building was more extensive than expected.",o:["A","An","The","No article"],c:2,x:"'The water damage' = specific (to this building). Definite article.",cat:"Articles"},
  {id:"g404",s:"He made _____ honest mistake on the invoice.",o:["a","an","the","no article"],c:1,x:"'An honest' — the 'h' in 'honest' is silent → vowel sound → 'an'.",cat:"Articles"},
  {id:"g405",s:"Our firm provides _____ legal advice to small businesses.",o:["a","an","the","no article"],c:3,x:"'Advice' = uncountable, general service → no article.",cat:"Articles"},
  {id:"g406",s:"_____ equipment ordered last week has finally arrived.",o:["A","An","The","No article"],c:2,x:"'The equipment' = specific (ordered last week). Definite article.",cat:"Articles"},
  {id:"g407",s:"Japan is _____ major trading partner of the United States.",o:["a","an","the","no article"],c:0,x:"'A major partner' — one of several. Indefinite article.",cat:"Articles"},
  {id:"g408",s:"The seminar will cover _____ basics of project management.",o:["a","an","the","no article"],c:2,x:"'The basics of' = specific set of fundamentals. Definite article.",cat:"Articles"},
  
  // ─── WORD FAMILIES (+10) ───
  {id:"g37",s:"The _____ of the new policy will take effect on January 1st.",o:["implement","implementation","implemented","implementing"],c:1,x:"'The' + _____ + 'of' = noun needed. 'Implementation' is the noun form.",cat:"Word Families"},
  {id:"g38",s:"All staff members are expected to dress _____.",o:["profession","professional","professionally","professionalism"],c:2,x:"Adverb modifies the verb 'dress'. 'Professionally' = how they dress.",cat:"Word Families"},
  {id:"g39",s:"Customer satisfaction has improved _____ since the new policy.",o:["drama","dramatic","dramatically","dramatize"],c:2,x:"Adverb 'dramatically' modifies the verb 'has improved'.",cat:"Word Families"},
  {id:"g40",s:"The board made a _____ to expand into Asian markets.",o:["decide","decision","decisive","decisively"],c:1,x:"'A' + _____ = noun needed. 'A decision'.",cat:"Word Families"},
  {id:"g41",s:"The product was _____ designed to meet safety standards.",o:["specific","specifically","specification","specify"],c:1,x:"Adverb 'specifically' modifies the past participle 'designed'.",cat:"Word Families"},
  {id:"g42",s:"We need a more _____ approach to project management.",o:["effect","effective","effectively","effectiveness"],c:1,x:"'A more _____' + noun = adjective. 'A more effective approach'.",cat:"Word Families"},
  {id:"g43",s:"Her _____ to the team has been outstanding.",o:["contribute","contribution","contributive","contributed"],c:1,x:"'Her' + _____ = possessive + noun. 'Her contribution'.",cat:"Word Families"},
  {id:"g44",s:"The CEO spoke _____ about the company's future plans.",o:["enthusiasm","enthusiastic","enthusiastically","enthuse"],c:2,x:"Adverb modifies the verb 'spoke'. 'Spoke enthusiastically'.",cat:"Word Families"},
  {id:"g45",s:"It is _____ that all employees complete the training by March.",o:["essentials","essential","essentially","essence"],c:1,x:"'It is _____' = adjective after 'is'. 'It is essential'.",cat:"Word Families"},
  {id:"g46",s:"The _____ rate for new hires has decreased this year.",o:["retain","retention","retentive","retaining"],c:1,x:"'The _____ rate' = noun modifying another noun. 'The retention rate'.",cat:"Word Families"},
  // ─── TENSES (+10) ───
  {id:"g47",s:"The company _____ its new headquarters last September.",o:["opens","opened","has opened","is opening"],c:1,x:"'Last September' = specific past time marker = past simple.",cat:"Tenses"},
  {id:"g48",s:"By the time the CEO arrived, the meeting _____.",o:["already started","has already started","had already started","already starts"],c:2,x:"Past perfect for action completed BEFORE another past action.",cat:"Tenses"},
  {id:"g49",s:"The IT department _____ the servers every weekend.",o:["updates","is updating","has updated","updated"],c:0,x:"'Every weekend' = habitual action = present simple.",cat:"Tenses"},
  {id:"g50",s:"We _____ for a new supplier since our current contract expired.",o:["look","looked","have been looking","are looking"],c:2,x:"'Since' = present perfect continuous for ongoing action from past.",cat:"Tenses"},
  {id:"g51",s:"Ms. Rodriguez _____ the Singapore office next Tuesday.",o:["visits","will visit","has visited","visited"],c:1,x:"'Next Tuesday' = future time marker. 'Will visit'.",cat:"Tenses"},
  {id:"g52",s:"The marketing team _____ the campaign materials right now.",o:["prepares","prepared","is preparing","has prepared"],c:2,x:"'Right now' = action in progress = present continuous.",cat:"Tenses"},
  {id:"g53",s:"Sales _____ by 15% compared to last year.",o:["increase","increased","have increased","are increasing"],c:2,x:"'Compared to last year' = result visible now = present perfect.",cat:"Tenses"},
  {id:"g54",s:"Before joining this firm, Mr. Tanaka _____ at Sony for ten years.",o:["works","worked","has worked","had worked"],c:3,x:"Past perfect: action BEFORE another past event (joining this firm).",cat:"Tenses"},
  {id:"g55",s:"The new regulation _____ into effect on April 1st.",o:["goes","went","has gone","is going"],c:0,x:"Scheduled future event = present simple. Timetables use present simple.",cat:"Tenses"},
  {id:"g56",s:"Our research team _____ on this project for over two years now.",o:["works","worked","has been working","had been working"],c:2,x:"'For over two years now' = present perfect continuous (ongoing).",cat:"Tenses"},
  // ─── PREPOSITIONS (+6) ───
  {id:"g57",s:"The conference will be held _____ March 15th.",o:["in","on","at","by"],c:1,x:"'On' + specific date. 'In' + month/year. 'At' + time.",cat:"Prepositions"},
  {id:"g58",s:"The new policy applies _____ all departments without exception.",o:["for","at","to","with"],c:2,x:"'Apply to' = affect or be relevant to.",cat:"Prepositions"},
  {id:"g59",s:"The manager insisted _____ reviewing the contract personally.",o:["in","on","for","to"],c:1,x:"'Insist on' + -ing = correct collocation.",cat:"Prepositions"},
  {id:"g60",s:"The delay was caused _____ a shortage of raw materials.",o:["for","from","by","with"],c:2,x:"'Caused by' = passive construction. Agent introduced by 'by'.",cat:"Prepositions"},
  {id:"g61",s:"The report was submitted well _____ advance of the deadline.",o:["on","at","in","by"],c:2,x:"'In advance of' = before. Fixed expression.",cat:"Prepositions"},
  {id:"g62",s:"Please refrain _____ using mobile phones during the presentation.",o:["of","to","from","for"],c:2,x:"'Refrain from' + -ing = correct collocation.",cat:"Prepositions"},
  // ─── CONNECTORS (+5) ───
  {id:"g63",s:"The product is affordable; _____, it is also eco-friendly.",o:["furthermore","despite","although","because"],c:0,x:"'Furthermore' adds information. Used after semicolon or full stop.",cat:"Connectors"},
  {id:"g64",s:"_____ of the high demand, the company increased production.",o:["Because","Despite","Although","However"],c:0,x:"'Because of' + noun phrase. 'Because' + clause.",cat:"Connectors"},
  {id:"g65",s:"The budget was reduced; _____, the project was completed on time.",o:["therefore","nevertheless","because","although"],c:1,x:"'Nevertheless' = despite that (contrast). The budget was cut BUT they still finished.",cat:"Connectors"},
  {id:"g66",s:"_____ sales in Europe declined, revenue in Asia grew by 20%.",o:["Whereas","Despite","However","Furthermore"],c:0,x:"'Whereas' + clause introduces a contrast between two facts.",cat:"Connectors"},
  {id:"g67",s:"Costs have risen sharply. _____, we need to adjust the budget.",o:["Although","Despite","Consequently","Furthermore"],c:2,x:"'Consequently' = as a result (cause and effect). Used in new sentence.",cat:"Connectors"},
  // ─── PASSIVE VOICE (+7) ───
  {id:"g68",s:"All visitors must _____ at the front desk before entering.",o:["register","be registered","registering","registered"],c:1,x:"'Must be registered' = passive with modal. Visitors are registered BY someone.",cat:"Passive Voice"},
  {id:"g69",s:"The award ceremony _____ at the Grand Hotel last Friday.",o:["held","was held","has held","is holding"],c:1,x:"Passive: 'The ceremony was held' (by organizers). Past time = 'last Friday'.",cat:"Passive Voice"},
  {id:"g70",s:"New employees _____ a company laptop on their first day.",o:["give","are given","giving","gave"],c:1,x:"Passive: employees RECEIVE the laptop. 'Are given' = present passive.",cat:"Passive Voice"},
  {id:"g71",s:"The contract _____ by both parties before the deadline.",o:["signed","was signing","had been signed","has signing"],c:2,x:"Past perfect passive: 'had been signed' = completed before the deadline.",cat:"Passive Voice"},
  {id:"g72",s:"Applications _____ until the position is filled.",o:["accept","are being accepted","accepting","have accepting"],c:1,x:"Present continuous passive: 'are being accepted' = ongoing process.",cat:"Passive Voice"},
  {id:"g73",s:"The damaged goods should _____ to the manufacturer.",o:["return","be returned","returning","returned"],c:1,x:"'Should be returned' = passive with modal 'should'.",cat:"Passive Voice"},
  {id:"g74",s:"It _____ that the merger will be completed by June.",o:["expects","is expected","expecting","has expecting"],c:1,x:"'It is expected that...' = impersonal passive construction.",cat:"Passive Voice"},
    {id:"g75",s:"The safety inspection _____ by an external auditor next Tuesday.",o:["conducts","will be conducted","conducting","has conducted"],c:1,x:"Future passive: 'will be conducted' — the auditor performs the action, not the inspection.",cat:"Passive Voice"},
  {id:"g76",s:"More than 500 units _____ from the warehouse last quarter.",o:["shipped","were shipped","have shipping","are shipping"],c:1,x:"Past passive: 'were shipped' — the units didn't ship themselves, someone shipped them.",cat:"Passive Voice"},
  {id:"g77",s:"All customer complaints should _____ within 48 hours.",o:["address","be addressed","addressing","addressed"],c:1,x:"Modal passive: should + be + past participle. 'Should be addressed'.",cat:"Passive Voice"},
  {id:"g78",s:"The building _____ currently _____ to meet new fire regulations.",o:["is...renovating","is...being renovated","has...renovated","was...renovating"],c:1,x:"Present continuous passive: 'is being renovated' — renovation is in progress right now.",cat:"Passive Voice"},
  {id:"g79",s:"Employees who _____ for the leadership program will be notified by email.",o:["select","are selected","selecting","have selecting"],c:1,x:"Present passive in relative clause: employees are selected BY someone.",cat:"Passive Voice"},
  // ─── SUBJECT-VERB AGREEMENT (+4) ───
  {id:"g75",s:"A number of employees _____ requested additional training.",o:["has","have","is","was"],c:1,x:"'A number of' = plural meaning ('many'). HAVE requested. (vs 'The number of' = singular.)",cat:"Subject-Verb Agreement"},
  {id:"g76",s:"Every manager and supervisor _____ expected to attend.",o:["are","is","were","have"],c:1,x:"'Every' + singular = singular verb. 'Every manager IS expected'.",cat:"Subject-Verb Agreement"},
  {id:"g77",s:"The equipment in all three laboratories _____ been upgraded.",o:["have","has","are","were"],c:1,x:"Subject = 'equipment' (singular uncountable). Ignore 'in all three laboratories'.",cat:"Subject-Verb Agreement"},
  {id:"g78",s:"Either the manager or the employees _____ going to lead the project.",o:["is","was","are","has"],c:2,x:"'Either...or' = verb agrees with NEAREST subject. 'Employees' = plural = ARE.",cat:"Subject-Verb Agreement"},
  // ─── COLLOCATIONS (+7) ───
  {id:"g79",s:"The company plans to _____ a survey among its customers.",o:["conduct","make","do","perform"],c:0,x:"'Conduct a survey' = standard business collocation.",cat:"Collocations"},
  {id:"g80",s:"We need to _____ a decision before the end of the week.",o:["do","take","make","give"],c:2,x:"'Make a decision' = fixed collocation. Not 'do' or 'take' a decision.",cat:"Collocations"},
  {id:"g81",s:"The company _____ great importance to customer satisfaction.",o:["places","puts","attaches","All are correct"],c:3,x:"'Attach/place/put importance to' are all valid collocations.",cat:"Collocations"},
  {id:"g82",s:"We look forward to _____ from you soon.",o:["hear","hearing","heard","hears"],c:1,x:"'Look forward to' + -ing. 'To' here is a preposition, not infinitive marker.",cat:"Collocations"},
  {id:"g83",s:"The company has _____ measures to reduce costs.",o:["taken","made","done","given"],c:0,x:"'Take measures' = fixed collocation meaning to act on something.",cat:"Collocations"},
  {id:"g84",s:"Our team will _____ every effort to meet the deadline.",o:["do","make","take","give"],c:1,x:"'Make an effort' / 'make every effort' = fixed collocation.",cat:"Collocations"},
  {id:"g85",s:"The presentation _____ a strong impression on the investors.",o:["did","gave","made","took"],c:2,x:"'Make an impression' = standard collocation.",cat:"Collocations"},
  // ─── RELATIVE PRONOUNS (+5) ───
  {id:"g86",s:"The report, _____ was submitted last week, contains several errors.",o:["that","which","who","whom"],c:1,x:"'Which' for things in non-defining clauses (with commas). NOT 'that'.",cat:"Relative Pronouns"},
  {id:"g87",s:"The candidate _____ resume impressed us most will be interviewed.",o:["who","whose","which","whom"],c:1,x:"'Whose' = possession. The candidate's resume = whose resume.",cat:"Relative Pronouns"},
  {id:"g88",s:"The hotel _____ we stayed was near the conference center.",o:["which","where","that","whose"],c:1,x:"'Where' = relative adverb for places. 'The hotel where we stayed'.",cat:"Relative Pronouns"},
  {id:"g89",s:"The client _____ the proposal was sent has not yet responded.",o:["who","to whom","which","whose"],c:1,x:"'To whom' = formal. The proposal was sent TO the client.",cat:"Relative Pronouns"},
  {id:"g90",s:"That is the reason _____ the meeting was postponed.",o:["which","why","where","when"],c:1,x:"'Why' = relative adverb for reasons. 'The reason why'.",cat:"Relative Pronouns"},
  // ─── CONDITIONALS (+4) ───
  {id:"g91",s:"If the shipment _____ on time, we will meet the deadline.",o:["arrives","arrived","will arrive","would arrive"],c:0,x:"First conditional: If + present simple, will + verb. Real possibility.",cat:"Conditionals"},
  {id:"g92",s:"If we had invested earlier, we _____ higher profits now.",o:["will have","would have","would have had","had had"],c:1,x:"Mixed conditional: past condition + present result. 'Would have' (now).",cat:"Conditionals"},
  {id:"g93",s:"_____ the client cancel, we will need to find a replacement.",o:["Should","Would","Could","Had"],c:0,x:"'Should the client cancel' = formal inversion of 'If the client should cancel'.",cat:"Conditionals"},
  {id:"g94",s:"If the report _____ ready, we could have presented it yesterday.",o:["was","had been","were","has been"],c:1,x:"Third conditional: If + past perfect, would/could + have + past participle.",cat:"Conditionals"},
  // ─── COMPARATIVES (+2) ───
  {id:"g95",s:"The new system is _____ less expensive than the previous one.",o:["consider","considerable","considerably","consideration"],c:2,x:"'Considerably' (adverb) modifies 'less expensive' (comparative).",cat:"Comparatives"},
  {id:"g96",s:"This quarter's results are the _____ in the company's history.",o:["good","better","best","most good"],c:2,x:"Superlative: 'the' + best (irregular: good → better → best).",cat:"Comparatives"},
  // ─── GERUNDS VS INFINITIVES (+2) ───
  {id:"g97",s:"The company cannot afford _____ any more employees.",o:["losing","to lose","lose","lost"],c:1,x:"'Afford' takes infinitive (to). Cannot afford to lose.",cat:"Gerunds vs Infinitives"},
  {id:"g98",s:"Do you mind _____ the door? It's quite noisy outside.",o:["to close","closing","close","closed"],c:1,x:"'Mind' always takes gerund (-ing). Do you mind closing...?",cat:"Gerunds vs Infinitives"},
  // ─── ARTICLES / QUANTIFIERS (+2) ───
  {id:"g99",s:"_____ information in this report is confidential.",o:["A","An","The","Some"],c:2,x:"'The' = specific information (in THIS report). Definite article for specific reference.",cat:"Articles"},
  {id:"g100",s:"_____ employees who wish to participate should register by Friday.",o:["All","Every","Each","The whole"],c:0,x:"'All employees' (plural). 'Every/Each' + singular noun. 'All' fits with plural 'employees'.",cat:"Articles"},
  {id:"g100",s:"_____ employees who wish to participate should register by Friday.",o:["All","Every","Each","The whole"],c:0,x:"'All employees' (plural). 'Every/Each' + singular noun. 'All' fits with plural 'employees'.",cat:"Articles"},
  // ─── BATCH 2 (g101–g130) ───
  // ─── ARTICLES / QUANTIFIERS (+4) ───
  {id:"g101",s:"We need to hire _____ accountant before the end of the quarter.",o:["a","an","the","some"],c:1,x:"'An' before vowel sound. 'Accountant' starts with a vowel sound.",cat:"Articles"},
  {id:"g102",s:"Could you pass me _____ file on your desk? The one with the blue cover.",o:["a","an","the","some"],c:2,x:"'The' = specific file already identified ('the one with the blue cover').",cat:"Articles"},
  {id:"g103",s:"_____ furniture in the new office was ordered from a local supplier.",o:["A","An","The","Some"],c:2,x:"'The furniture' = specific (in the new office). 'Furniture' is uncountable — no 'a/an'.",cat:"Articles"},
  {id:"g104",s:"Mr. Park has _____ experience in international logistics.",o:["a","an","extensive","the"],c:2,x:"'Experience' is uncountable — no 'a/an'. 'Extensive' (adj) fits: 'extensive experience'.",cat:"Articles"},
  // ─── COMPARATIVES (+3) ───
  {id:"g105",s:"This quarter's sales figures are _____ higher than last year's.",o:["significant","significance","significantly","signify"],c:2,x:"Adverb 'significantly' modifies the comparative 'higher'.",cat:"Comparatives"},
  {id:"g106",s:"Of all the proposals submitted, Ms. Chen's was the _____.",o:["more convincing","most convincing","convincing","as convincing"],c:1,x:"Superlative with 'of all': 'the most convincing'. Three or more = superlative.",cat:"Comparatives"},
  {id:"g107",s:"The new printer is not _____ fast as the one it replaced.",o:["so","as","more","much"],c:1,x:"Negative comparison: 'not as ... as'. Both 'so' and 'as' are grammatically possible, but 'as...as' is standard in TOEIC.",cat:"Comparatives"},
  // ─── CONDITIONALS (+3) ───
  {id:"g108",s:"If the contract _____ signed by Friday, we will lose the deal.",o:["isn't","weren't","won't be","wouldn't be"],c:0,x:"First conditional: If + present simple, will + base verb. Real possibility.",cat:"Conditionals"},
  {id:"g109",s:"Had the shipment arrived on time, the client _____ so frustrated.",o:["wouldn't be","wouldn't have been","won't be","isn't"],c:1,x:"Third conditional: Had + past participle, would have + past participle. Unreal past.",cat:"Conditionals"},
  {id:"g110",s:"If I _____ you, I would accept the offer immediately.",o:["am","was","were","be"],c:2,x:"Second conditional: 'If I were you' — subjunctive mood. 'Were' for all persons in formal English.",cat:"Conditionals"},
  // ─── GERUNDS vs INFINITIVES (+3) ───
  {id:"g111",s:"The director agreed _____ the budget for the marketing campaign.",o:["increasing","to increase","increase","increased"],c:1,x:"'Agree' takes infinitive (to). 'Agreed to increase'.",cat:"Gerunds vs Infinitives"},
  {id:"g112",s:"Would you consider _____ the deadline to next month?",o:["to extend","extending","extend","extended"],c:1,x:"'Consider' always takes gerund (-ing). 'Consider extending'.",cat:"Gerunds vs Infinitives"},
  {id:"g113",s:"The staff avoided _____ any comments during the investigation.",o:["to make","making","make","made"],c:1,x:"'Avoid' always takes gerund (-ing). 'Avoided making'.",cat:"Gerunds vs Infinitives"},
  // ─── RELATIVE PRONOUNS (+3) ───
  {id:"g114",s:"The building _____ the conference will be held is on Park Avenue.",o:["which","where","that","whose"],c:1,x:"'Where' = relative adverb for places. 'The building where the conference will be held'.",cat:"Relative Pronouns"},
  {id:"g115",s:"Employees _____ performance exceeds expectations will receive a bonus.",o:["who","whom","whose","which"],c:2,x:"'Whose' = possession. The employees' performance = whose performance.",cat:"Relative Pronouns"},
  {id:"g116",s:"The consultant _____ we hired last month has already improved efficiency.",o:["who","whom","whose","which"],c:0,x:"'Who' = subject of 'has improved'. The consultant has improved (not 'whom').",cat:"Relative Pronouns"},
  // ─── COLLOCATIONS (+4) ───
  {id:"g117",s:"The board will _____ a meeting to discuss the acquisition.",o:["hold","make","do","have"],c:0,x:"'Hold a meeting' = standard business collocation. 'Have a meeting' is also valid but 'hold' is more formal.",cat:"Collocations"},
  {id:"g118",s:"Please _____ sure that all documents are signed before submission.",o:["do","make","take","give"],c:1,x:"'Make sure' = fixed collocation. Not 'do sure' or 'take sure'.",cat:"Collocations"},
  {id:"g119",s:"The company _____ an apology for the delay in processing orders.",o:["made","issued","gave","did"],c:1,x:"'Issue an apology' = formal business collocation. 'Make an apology' is possible but less formal.",cat:"Collocations"},
  {id:"g120",s:"We need to _____ advantage of the current market conditions.",o:["make","do","take","give"],c:2,x:"'Take advantage of' = fixed collocation. Not 'make' or 'do' advantage.",cat:"Collocations"},
  // ─── SUBJECT-VERB AGREEMENT (+3) ───
  {id:"g121",s:"The number of complaints _____ decreased significantly this quarter.",o:["have","has","are","were"],c:1,x:"'The number of' = singular (the number itself). HAS decreased. (vs 'A number of' = plural.)",cat:"Subject-Verb Agreement"},
  {id:"g122",s:"Neither the supervisor nor the team members _____ aware of the change.",o:["was","is","were","has been"],c:2,x:"'Neither...nor' = verb agrees with NEAREST subject. 'Team members' = plural = WERE.",cat:"Subject-Verb Agreement"},
  {id:"g123",s:"Each of the candidates _____ required to submit a portfolio.",o:["are","is","were","have"],c:1,x:"'Each of' = always singular. 'Each of the candidates IS required'.",cat:"Subject-Verb Agreement"},
  // ─── CONNECTORS (+3) ───
  {id:"g124",s:"The product launch was delayed; _____, customer interest remained high.",o:["however","because","although","despite"],c:0,x:"'However' after semicolon shows contrast. 'Although/Despite' need different structure.",cat:"Connectors"},
  {id:"g125",s:"_____ the team worked overtime, they were unable to meet the deadline.",o:["Even though","Despite","However","Furthermore"],c:0,x:"'Even though' + clause (subject + verb). 'Despite' needs a noun phrase, not a clause.",cat:"Connectors"},
  {id:"g126",s:"Profits rose in Q1; _____, they declined sharply in Q2.",o:["moreover","in addition","conversely","therefore"],c:2,x:"'Conversely' = introduces opposite situation. Q1 up, Q2 down = contrast/reversal.",cat:"Connectors"},
  // ─── TENSES (+2) ───
  {id:"g127",s:"By the time the auditors arrive, we _____ all the documents.",o:["prepare","will have prepared","have prepared","are preparing"],c:1,x:"'By the time' + present = future perfect in main clause. Action completed before arrival.",cat:"Tenses"},
  {id:"g128",s:"The company _____ its headquarters to Berlin three years ago.",o:["relocates","has relocated","relocated","had relocated"],c:2,x:"'Three years ago' = past simple. Specific past time marker.",cat:"Tenses"},
  // ─── PREPOSITIONS (+2) ───
  {id:"g129",s:"The new policy will go into _____ on January 1st.",o:["action","effect","place","practice"],c:1,x:"'Go into effect' = become active/operational. Fixed expression for laws and policies.",cat:"Prepositions"},
  {id:"g130",s:"Ms. Rivera is in _____ of the company's European operations.",o:["charge","control","lead","head"],c:0,x:"'In charge of' = responsible for managing. Fixed prepositional phrase.",cat:"Prepositions"},
{id:"g130",s:"Ms. Rivera is in _____ of the company's European operations.",o:["charge","control","lead","head"],c:0,x:"'In charge of' = responsible for managing. Fixed prepositional phrase.",cat:"Prepositions"},
  // ─── BATCH 3 (g131–g160) ───
  // ─── PASSIVE VOICE (+4) ───
  {id:"g131",s:"The factory floor _____ thoroughly before the safety inspection.",o:["cleaned","was cleaned","has cleaning","is cleaning"],c:1,x:"Passive: the floor was cleaned (by someone). Past simple passive for completed past action.",cat:"Passive Voice"},
  {id:"g132",s:"Over 300 complaints _____ since the product recall was announced.",o:["received","have been received","are receiving","had receiving"],c:1,x:"'Since' = present perfect passive. 'Have been received' — action started in past, continues to now.",cat:"Passive Voice"},
  {id:"g133",s:"The faulty items are currently _____ by the quality team.",o:["inspecting","inspected","being inspected","been inspected"],c:2,x:"Present continuous passive: 'are being inspected' = in progress right now.",cat:"Passive Voice"},
  {id:"g134",s:"The project deadline cannot _____ without the client's approval.",o:["extend","be extended","extending","to extend"],c:1,x:"Modal passive: 'cannot be extended'. Cannot + be + past participle.",cat:"Passive Voice"},
  // ─── ARTICLES (+3) ───
  {id:"g135",s:"_____ CEO announced the restructuring plan at the annual meeting.",o:["A","An","The","—"],c:2,x:"'The CEO' = specific person known to both speaker and listener. Definite article.",cat:"Articles"},
  {id:"g136",s:"We are looking for _____ experienced project manager to join our team.",o:["a","an","the","—"],c:1,x:"'An' before vowel sound. 'Experienced' starts with a vowel sound. Non-specific person = indefinite.",cat:"Articles"},
  {id:"g137",s:"_____ advice she gave during the meeting proved extremely useful.",o:["A","An","The","Some"],c:2,x:"'The advice' = specific advice (she gave during the meeting). 'Advice' is uncountable — no 'a/an'.",cat:"Articles"},
  // ─── COMPARATIVES (+3) ───
  {id:"g138",s:"The more carefully you proofread, the _____ errors you will find.",o:["few","fewer","fewest","less"],c:1,x:"'The more... the fewer' = double comparative. 'Fewer' for countable nouns (errors).",cat:"Comparatives"},
  {id:"g139",s:"Our delivery times are _____ to those of our main competitors.",o:["similar","similarly","similarity","more similar"],c:0,x:"'Similar to' = adjective + preposition. Fixed collocation. Not 'similarly to'.",cat:"Comparatives"},
  {id:"g140",s:"The premium package is almost three times as _____ as the basic one.",o:["expensive","expensively","expense","more expensive"],c:0,x:"'Three times as [adjective] as' = multiplier comparison. Base adjective, no comparative form.",cat:"Comparatives"},
  // ─── CONDITIONALS (+3) ───
  {id:"g141",s:"Unless the payment _____ by the 15th, a late fee will be applied.",o:["receives","is received","will receive","receiving"],c:1,x:"'Unless' = 'if not'. Passive needed: payment is received (by us). Present simple in conditional clause.",cat:"Conditionals"},
  {id:"g142",s:"We would have launched on schedule if the supplier _____ the materials sooner.",o:["delivers","delivered","had delivered","would deliver"],c:2,x:"Third conditional: if + past perfect. 'Had delivered' = unreal past condition.",cat:"Conditionals"},
  {id:"g143",s:"If you _____ any questions, please do not hesitate to contact us.",o:["had","have","would have","will have"],c:1,x:"First conditional / zero conditional: 'If you have' = present simple. Polite business formula.",cat:"Conditionals"},
  // ─── GERUNDS vs INFINITIVES (+3) ───
  {id:"g144",s:"The manager suggested _____ the team meeting to Thursday.",o:["to move","moving","move","to moving"],c:1,x:"'Suggest' takes gerund (-ing). 'Suggested moving'. Never 'suggest to do'.",cat:"Gerunds vs Infinitives"},
  {id:"g145",s:"We can't risk _____ the contract over a minor disagreement.",o:["to lose","losing","lose","to losing"],c:1,x:"'Risk' always takes gerund (-ing). 'Risk losing'.",cat:"Gerunds vs Infinitives"},
  {id:"g146",s:"The company expects all staff _____ the new guidelines by Monday.",o:["following","to follow","follow","to following"],c:1,x:"'Expect + object + to-infinitive'. 'Expects staff to follow'.",cat:"Gerunds vs Infinitives"},
  // ─── RELATIVE PRONOUNS (+3) ───
  {id:"g147",s:"The year _____ the company was founded was marked by a major recession.",o:["which","when","where","that"],c:1,x:"'When' = relative adverb for time. 'The year when the company was founded'.",cat:"Relative Pronouns"},
  {id:"g148",s:"Ms. Nakamura, _____ I worked with in Seoul, is now heading the Paris office.",o:["who","whom","that","whose"],c:1,x:"'Whom' = object pronoun. 'I worked with HER' → 'whom I worked with'. Formal register for TOEIC.",cat:"Relative Pronouns"},
  {id:"g149",s:"The department _____ budget was cut will need to prioritize differently.",o:["who","which","whose","that"],c:2,x:"'Whose' = possession. The department's budget = whose budget. Works for things too, not just people.",cat:"Relative Pronouns"},
  // ─── COLLOCATIONS (+3) ───
  {id:"g150",s:"The company has _____ significant progress in reducing waste.",o:["done","made","taken","given"],c:1,x:"'Make progress' = fixed collocation. Not 'do progress' or 'take progress'.",cat:"Collocations"},
  {id:"g151",s:"We _____ priority to customer satisfaction above all else.",o:["make","do","give","take"],c:2,x:"'Give priority to' = fixed collocation. Also valid: 'give something priority'.",cat:"Collocations"},
  {id:"g152",s:"The team has _____ into account all of the client's requirements.",o:["put","made","taken","given"],c:2,x:"'Take into account' = fixed collocation meaning to consider. Also: 'take account of'.",cat:"Collocations"},
  // ─── TENSES (+3) ───
  {id:"g153",s:"The marketing team _____ on the campaign since early January.",o:["works","is working","has been working","worked"],c:2,x:"'Since early January' = present perfect continuous. Action started in past, still ongoing.",cat:"Tenses"},
  {id:"g154",s:"Once the renovations _____, the office will reopen to the public.",o:["complete","are completed","will complete","completing"],c:1,x:"'Once' + present simple (or passive) for future time clause. Not 'will'. Passive because renovations are completed by workers.",cat:"Tenses"},
  {id:"g155",s:"Last quarter, the firm _____ a record number of new clients.",o:["attracts","attracted","has attracted","was attracting"],c:1,x:"'Last quarter' = specific past time. Past simple: 'attracted'.",cat:"Tenses"},
  // ─── SUBJECT-VERB AGREEMENT (+2) ───
  {id:"g156",s:"The committee _____ divided on how to allocate the remaining funds.",o:["are","is","have","were"],c:1,x:"'Committee' = collective noun, usually singular in American English. 'The committee IS divided.'",cat:"Subject-Verb Agreement"},
  {id:"g157",s:"Three hours _____ enough time to complete the assessment.",o:["are","is","were","have"],c:1,x:"Time/money/distance as a unit = singular. 'Three hours IS enough' (treated as one block of time).",cat:"Subject-Verb Agreement"},
  // ─── PREPOSITIONS (+2) ───
  {id:"g158",s:"The training session will take place _____ March 5th and 7th.",o:["from","between","during","within"],c:1,x:"'Between' + two specific points. 'Between March 5th and 7th'. 'From' needs 'to'.",cat:"Prepositions"},
  {id:"g159",s:"All expenses must be approved _____ advance by the department head.",o:["on","at","in","by"],c:2,x:"'In advance' = beforehand. Fixed prepositional phrase.",cat:"Prepositions"},
  // ─── CONNECTORS (+1) ───
  {id:"g160",s:"The prototype passed all safety tests; _____, it is now ready for production.",o:["therefore","however","although","despite"],c:0,x:"'Therefore' = as a result (cause → effect). Tests passed → ready for production. Logical consequence.",cat:"Connectors"},
  // ─── ARTICLES BATCH 2 (g161–g165) ───
  {id:"g161",s:"We need to buy _____ new equipment for the laboratory.",o:["a","an","some","the"],c:2,x:"'Equipment' is uncountable — no 'a/an'. 'Some' works for an unspecified quantity of uncountable nouns.",cat:"Articles"},
  {id:"g162",s:"_____ honesty is the most important quality in a business partner.",o:["A","An","The","—"],c:3,x:"Zero article for abstract nouns used in a general sense. 'Honesty' in general, not specific honesty.",cat:"Articles"},
  {id:"g163",s:"She was appointed _____ chairperson of the committee last month.",o:["a","an","the","—"],c:3,x:"Zero article after 'appointed/elected/named' + unique title. 'Appointed chairperson' (not 'the chairperson').",cat:"Articles"},
  {id:"g164",s:"Could you give me _____ update on the merger negotiations?",o:["a","an","the","—"],c:1,x:"'An' before vowel sound. 'Update' starts with a vowel sound. Non-specific = indefinite article.",cat:"Articles"},
  {id:"g165",s:"_____ research conducted by our team suggests that demand will increase.",o:["A","An","The","—"],c:2,x:"'The research' = specific research (conducted by our team). Definite article for identified/specified nouns.",cat:"Articles"},
  // ─── CONDITIONALS (+5) ───
  {id:"g80",s:"If demand _____, we will need to hire additional staff.",o:["increases","increased","will increase","would increase"],c:0,x:"First conditional: If + present simple, will + base verb. Real/likely future situation.",cat:"Conditionals"},
  {id:"g81",s:"Had the shipment arrived on time, we _____ the deadline.",o:["met","would meet","would have met","will meet"],c:2,x:"Third conditional (inverted): Had + past participle, would have + past participle. Unreal past.",cat:"Conditionals"},
  {id:"g82",s:"If I _____ you, I would accept the promotion without hesitation.",o:["am","was","were","will be"],c:2,x:"Second conditional: If I WERE (subjunctive) — 'were' for all persons in formal/TOEIC English.",cat:"Conditionals"},
  {id:"g83",s:"The warranty will be voided _____ the product is not used as directed.",o:["unless","if","whether","so that"],c:1,x:"First conditional with 'if': the warranty WILL be voided IF the product is misused.",cat:"Conditionals"},
  {id:"g84",s:"_____ the budget been approved earlier, we could have started in January.",o:["Should","Had","Would","If"],c:1,x:"Third conditional (inversion): 'Had the budget been approved' = 'If the budget had been approved'.",cat:"Conditionals"},
 
  // ─── RELATIVE PRONOUNS (+5) ───
  {id:"g85",s:"The candidate _____ résumé impressed the panel was offered the position.",o:["who","whose","whom","which"],c:1,x:"'Whose' = possessive relative pronoun. 'The candidate whose résumé...' (his/her résumé).",cat:"Relative Pronouns"},
  {id:"g86",s:"The conference, _____ was attended by over 2,000 delegates, lasted three days.",o:["that","which","who","whose"],c:1,x:"Non-defining relative clause (with commas) uses 'which', never 'that'.",cat:"Relative Pronouns"},
  {id:"g87",s:"Employees _____ wish to enroll in the program should contact HR by Friday.",o:["whom","which","who","whose"],c:2,x:"'Who' = subject of the relative clause. Employees WHO wish... (they wish = subject).",cat:"Relative Pronouns"},
  {id:"g88",s:"The building in _____ the head office is located was built in 1965.",o:["that","where","which","what"],c:2,x:"After a preposition: 'in WHICH'. 'That' cannot follow a preposition directly.",cat:"Relative Pronouns"},
  {id:"g89",s:"Ms. Lee is the executive to _____ you should address your complaint.",o:["who","whose","which","whom"],c:3,x:"After a preposition: 'to WHOM'. 'Whom' is the object form of 'who'.",cat:"Relative Pronouns"},
 
  // ─── COMPARATIVES (+5) ───
  {id:"g90",s:"The new model is far _____ reliable than the previous one.",o:["most","more","as","very"],c:1,x:"'Far more' = intensified comparative. 'Far/much/significantly + more + adjective'.",cat:"Comparatives"},
  {id:"g91",s:"Of the three candidates, Ms. Tanaka has the _____ relevant experience.",o:["more","most","much","very"],c:1,x:"Superlative with 3+ items: 'the most relevant'. 'More' is for comparing two.",cat:"Comparatives"},
  {id:"g92",s:"Sales this year are nearly twice _____ high as last year.",o:["so","as","more","than"],c:1,x:"'Twice AS high AS' — multiplier comparison. Number + as + adj + as.",cat:"Comparatives"},
  {id:"g93",s:"This quarter's profits are _____ lower than what analysts predicted.",o:["significant","significantly","significance","more significant"],c:1,x:"Adverb modifying a comparative: 'significantly lower'. Not adjective 'significant'.",cat:"Comparatives"},
  {id:"g94",s:"The later the project starts, the _____ expensive it becomes.",o:["more","most","much","very"],c:0,x:"Double comparative: 'The later..., the more expensive...' Parallel structure.",cat:"Comparatives"},
 
  // ─── GERUNDS vs INFINITIVES (+5) ───
  {id:"g95",s:"The company avoided _____ any unnecessary expenses during the downturn.",o:["to incur","incurring","incur","incurred"],c:1,x:"'Avoid' always takes a gerund (-ing). Avoid incurring.",cat:"Gerunds vs Infinitives"},
  {id:"g96",s:"We expect all participants _____ the terms and conditions before registering.",o:["reading","read","to read","having read"],c:2,x:"'Expect + object + to-infinitive'. We expect participants TO READ.",cat:"Gerunds vs Infinitives"},
  {id:"g97",s:"The manager postponed _____ a decision until more data was available.",o:["to make","making","make","made"],c:1,x:"'Postpone' takes a gerund. Postponed making a decision.",cat:"Gerunds vs Infinitives"},
  {id:"g98",s:"She seems _____ very familiar with the new accounting software.",o:["being","to be","be","been"],c:1,x:"'Seem' takes an infinitive (to). She seems TO BE familiar.",cat:"Gerunds vs Infinitives"},
  {id:"g99",s:"The employees were asked _____ overtime until the project was delivered.",o:["working","to work","work","worked"],c:1,x:"Passive + infinitive: 'were asked TO WORK'. Ask/tell/advise + object + to-infinitive.",cat:"Gerunds vs Infinitives"},
 
  // ─── SUBJECT-VERB AGREEMENT (+5) ───
  {id:"g100",s:"A number of employees _____ requested additional training this quarter.",o:["has","is","have","was"],c:2,x:"'A number of' = plural meaning (= many). HAVE requested. vs 'THE number of' = singular.",cat:"Subject-Verb Agreement"},
  {id:"g101",s:"The equipment delivered to both offices _____ still under warranty.",o:["are","were","have","is"],c:3,x:"'Equipment' is uncountable = singular. The equipment IS under warranty.",cat:"Subject-Verb Agreement"},
  {id:"g102",s:"Every one of the proposals submitted last week _____ been reviewed.",o:["have","are","has","were"],c:2,x:"'Every one' = singular. Every one HAS been reviewed. Don't be fooled by 'proposals' (plural).",cat:"Subject-Verb Agreement"},
  {id:"g103",s:"The news about the upcoming layoffs _____ not yet been confirmed.",o:["have","are","has","were"],c:2,x:"'News' is uncountable singular. The news HAS not been confirmed.",cat:"Subject-Verb Agreement"},
  {id:"g104",s:"Not only the director but also the board members _____ expected to attend.",o:["is","was","has","are"],c:3,x:"'Not only A but also B' — verb agrees with B (closest). 'Board members' = plural → ARE.",cat:"Subject-Verb Agreement"},
 
  // ─── CONNECTORS (+5) ───
  {id:"g105",s:"The product is popular among consumers; _____, production has been increased.",o:["nevertheless","accordingly","although","despite"],c:1,x:"'Accordingly' = as a result, logically. Cause → consequence.",cat:"Connectors"},
  {id:"g106",s:"_____ completing the online form, applicants must submit two references.",o:["In addition to","However","Therefore","Despite"],c:0,x:"'In addition to' + -ing/noun. Adds an extra requirement.",cat:"Connectors"},
  {id:"g107",s:"The workshop was cancelled _____ insufficient enrollment.",o:["because","due to","although","so that"],c:1,x:"'Due to' + noun phrase (no clause). 'Because' would need a clause: 'because enrollment was insufficient'.",cat:"Connectors"},
  {id:"g108",s:"Mr. Sato agreed to the terms; _____, he signed the contract immediately.",o:["otherwise","whereas","furthermore","therefore"],c:3,x:"'Therefore' = consequence. He agreed, therefore he signed.",cat:"Connectors"},
  {id:"g109",s:"The CEO will visit the Tokyo office _____ the Osaka branch next week.",o:["as well as","however","therefore","despite"],c:0,x:"'As well as' = in addition to. Connecting two parallel items.",cat:"Connectors"},
];

